'use strict';
const fs=require('fs'),vm=require('vm'),assert=require('assert/strict');
const source=fs.readFileSync(process.argv[2]||'/var/minis/workspace/weibo_sources/weibo_json.js','utf8');
const VM_TIMEOUT=Number(process.argv[3]||5000);
if(!Number.isInteger(VM_TIMEOUT)||VM_TIMEOUT<1||VM_TIMEOUT>15000)throw new Error('VM timeout must be 1..15000 ms');
const compiled=new vm.Script(source),KEY='weibo_adblock_config_v3',BASE='https://api.weibo.cn/__qx_weibo_settings__/';
function run(url,options={}){
 const store=options.store||{},writes=[],reads=[],network=[],done=[],timers=new Map();let next=1;
 const context={$request:{url,method:options.method||'GET',headers:options.headers||{}},console:{log(){},warn(){},error(){}},$done:x=>done.push(x),$environment:{'surge-version':'5.0.0'},$persistentStore:{read:k=>{reads.push(k);return store[k]??null;},write:(v,k)=>{writes.push([k,v]);if(options.writeFail)return false;store[k]=v;return true;}},$httpClient:{get:(o,cb)=>{network.push(o);if(options.networkReply)cb(...options.networkReply);else if(!options.hangNetwork)cb('mock blocked',{status:0},'');}},setTimeout:(f,t)=>{const id=next++;timers.set(id,{f,t});return id;},clearTimeout:id=>timers.delete(id)};
 if('requestBody'in options)context.$request.body=options.requestBody;
 if('responseBody'in options)context.$response={body:options.responseBody,headers:{},status:200};
 Object.assign(context,options.globals||{});
 const ctx=vm.createContext(context);compiled.runInContext(ctx,{timeout:VM_TIMEOUT});
 return {done,writes,reads,network,store,ctx,timers,flush(){for(const [id,t]of [...timers]){timers.delete(id);t.f();}}};
}
const json=x=>JSON.parse(x.done[0].response.body),response=x=>x.done[0].response;
const headers={'Content-Type':'application/json; charset=utf-8','X-Weibo-Settings':'1',Origin:'https://api.weibo.cn'};
const post=(path,payload,extra={})=>run(BASE+path,{method:'POST',headers,requestBody:typeof payload==='string'?payload:JSON.stringify(payload),...extra});
let pass=0;function check(name,fn){try{fn();pass++;}catch(e){console.error('FAIL '+name+': '+e.message);process.exitCode=1;}}
const baseline=run(BASE+'api/config'),defaults=json(baseline).config;
check('native config',()=>{assert.equal(baseline.done.length,1);assert.equal(response(baseline).status,200);assert.equal(json(baseline).service,'weibo-qx-settings');assert.equal(json(baseline).settings.length,63);assert.equal(baseline.network.length,0);assert.equal(baseline.writes.length,0);});
check('native html',()=>{const r=run(BASE);assert.equal(response(r).status,200);assert.match(response(r).body,/<!doctype html>/i);assert.match(response(r).body,/async function commit/);assert.match(response(r).body,/function collect/);assert.match(response(r).headers['Content-Type'],/text\/html/);assert.equal(r.network.length,0);assert.equal(r.writes.length,0);});
const store={[KEY]:JSON.stringify({blockedUserIds:['1234567890123456789'],hiddenProfileGroups:[],videoChannelTitleOverrides:{推荐:'自选'},homeAutoRefresh:null,homeStartupTab:null,followingTimelineOrder:null,removeFeedAds:false})};
check('save own config and retain omissions',()=>{const r=post('api/save',{hideHomeInterestPosts:false},{store});assert.equal(response(r).status,200);assert.equal(r.writes.length,1);assert.equal(r.writes[0][0],KEY);assert.equal(json(r).config.hideHomeInterestPosts,false);assert.equal(json(r).config.removeFeedAds,false);assert.equal(json(r).config.homeAutoRefresh,null);assert.deepEqual(json(r).config.blockedUserIds,['1234567890123456789']);assert.deepEqual(json(r).config.hiddenProfileGroups,[]);assert.deepEqual(json(r).config.videoChannelTitleOverrides,{推荐:'自选'});assert.equal(Object.keys(JSON.parse(store[KEY])).length,63);assert.equal(r.network.length,0);});
check('read persisted config',()=>assert.equal(json(run(BASE+'api/config',{store})).config.hideHomeInterestPosts,false));
check('reset exact defaults',()=>{const r=post('api/reset',{reset:true},{store});assert.equal(response(r).status,200);assert.deepEqual(json(r).config,defaults);assert.equal(r.writes.length,1);assert.equal(r.network.length,0);});
for(const [name,payload]of [['malformed','{'],['empty',{}],['array',[]],['null',null],['unknown',{notASetting:true}],['wrongtype',{enabled:'false'}],['custom empty',{startupImageSource:'custom'}],['oversize',' '.repeat(65537)]])check(name,()=>{const r=post('api/save',payload);assert.equal(response(r).status,400);assert.equal(r.writes.length,0);assert.equal(r.network.length,0);});
check('request body required',()=>{const r=run(BASE+'api/save',{method:'POST',headers});assert.equal(response(r).status,400);assert.equal(r.writes.length,0);});
check('invalid reset',()=>assert.equal(response(post('api/reset',{reset:true,x:1})).status,400));
check('write failure',()=>assert.equal(response(post('api/save',{enabled:false},{writeFail:true})).status,500));
check('wrong origin',()=>assert.equal(response(post('api/save',{enabled:false},{headers:{...headers,Origin:'https://invalid.example'}})).status,403));
check('wrong header',()=>assert.equal(response(post('api/save',{enabled:false},{headers:{'Content-Type':'application/json'}})).status,403));
check('method gate',()=>assert.equal(response(run(BASE+'api/config',{method:'POST'})).status,405));
check('unknown settings path closed',()=>{const r=run(BASE+'api/missing');assert.equal(response(r).status,404);assert.equal(r.network.length,0);});
check('unsupported response url unchanged',()=>{const body='{"items":[1]}',r=run('https://invalid.example/other',{responseBody:body});assert.equal(r.done[0].body,body);assert.equal(r.network.length,0);});
check('invalid response unchanged',()=>{const body='<broken>',r=run('https://api.weibo.cn/2/statuses/container_timeline_hot',{responseBody:body});assert.equal(r.done[0].body,body);});
check('surge explicit beats prefs task',()=>{const r=run(BASE+'api/config',{globals:{$prefs:{valueForKey(){throw Error('wrong prefs');}},$task:{fetch(){throw Error('wrong task');}}}});assert.equal(response(r).status,200);assert.equal(r.reads[0],KEY);});
check('native without environment fallback',()=>{const r=run(BASE+'api/config',{globals:{$environment:undefined}});assert.equal(response(r).status,200);assert.equal(r.reads[0],KEY);});
check('false detection when QX shim added',()=>{const r=run(BASE+'api/config',{globals:{$environment:undefined,$prefs:{valueForKey:()=>null}}});assert.equal(r.done[0].status,'HTTP/1.1 200 OK');assert.equal(r.done[0].response,undefined);assert.equal(r.reads.length,0);});
check('no body response passthrough',()=>assert.deepEqual(Object.keys(run('https://api.weibo.cn/2/checkin/show').done[0]),[]));
check('corrupt store fallback',()=>assert.deepEqual(json(run(BASE+'api/config',{store:{[KEY]:'{invalid'}})).config,defaults));
// Additional rewrite/UI fixtures appended below.
module.exports={run,post,check,json,response,BASE,KEY,headers,source,defaults};
if(require.main===module)process.on('exit',()=>console.log('PASS '+pass));

const outBody=r=>JSON.parse(r.done[0].body);
const rewrite=(path,body,config={},extra={})=>run(/^https?:/.test(path)?path:'https://api.weibo.cn'+path,{responseBody:typeof body==='string'?body:JSON.stringify(body),store:{[KEY]:JSON.stringify(config)},...extra});
const feed={items:[{category:'feed',data:{idstr:'ad',promotion:{type:'ad'}}},{category:'feed',data:{idstr:'blocked',user:{idstr:'90071992547409931'}}},{category:'feed',data:{idstr:'keep',user:{idstr:'7'},bottom_bar_dyna:{cell_item:{ai_search:{},keep:{}}},page_info:{media_info:{play_completion_actions:[1]}}}}]};
check('feed ad blocked IDs and UI removed',()=>{const r=rewrite('/2/statuses/container_timeline_hot?mock=1',feed,{blockedUserIds:['90071992547409931']});const o=outBody(r);assert.equal(o.items.length,1);assert.equal(o.items[0].data.idstr,'keep');assert.equal(o.items[0].data.bottom_bar_dyna.cell_item.ai_search,undefined);assert.deepEqual(o.items[0].data.page_info.media_info.play_completion_actions,[]);assert.equal(r.network.length,0);});
check('custom toggles disable filtering',()=>{const r=rewrite('/2/statuses/container_timeline_hot',feed,{removeFeedAds:false,hideFeedAiButton:false,hidePlaybackCompletionActions:false});const o=outBody(r);assert.equal(o.items.length,3);assert.ok(o.items[2].data.bottom_bar_dyna.cell_item.ai_search);assert.deepEqual(o.items[2].data.page_info.media_info.play_completion_actions,[1]);});
check('disabled keeps body exact',()=>{const body=JSON.stringify(feed,null,2),r=rewrite('/2/statuses/container_timeline_hot',body,{enabled:false});assert.equal(r.done[0].body,body);});
check('search ads removed only selected',()=>{const o=outBody(rewrite('/2/searchall',feed));assert.equal(o.items.length,2);assert.equal(o.items[0].data.idstr,'blocked');});
check('video ads removed',()=>assert.equal(outBody(rewrite('/2/video/flow_stream',feed)).items.length,2));
check('search guess nonad removed',()=>{const o=outBody(rewrite('/2/cardlist',{items:[{category:'group',type:'vertical',header:{category:'search',type:'guess'},items:[1]},{category:'feed',data:{idstr:'keep'}}]}));assert.equal(o.items.length,1);assert.equal(o.items[0].category,'feed');});
check('discovery channel full content hidden',()=>{const o=outBody(rewrite('/2/search/container_timeline',{loadedInfo:{is_discover_channel:true},items:[{category:'feed',data:{idstr:'normal'}}],moreInfo:{noMore:false}}));assert.deepEqual(o.items,[]);assert.equal(o.moreInfo.noMore,true);});
check('home recommendations nonad removed',()=>{const item={from_tuijian:true,is_top:1,type:0,live_type:0,user:{},live_scheme:'sinaweibo://chatroom?mock=1'},o=outBody(rewrite('/2/live/media_homelist',{code:100000,data:[item,{...item,from_tuijian:false}]}));assert.equal(o.data.length,1);assert.equal(o.data[0].from_tuijian,false);});
check('checkin nonad removed',()=>assert.equal(outBody(rewrite('/2/checkin/show',{show:1,keep:'test'})).show,0));
check('reminder nonad removed',()=>assert.equal(outBody(rewrite('/2/video/remind_info',{exist_remind:true})).exist_remind,false));
const BOOT='https://bootpreload.uve.weibo.com/v2/ad/preload',REAL='https://bootrealtime.uve.weibo.com/v3/ad/realtime',LUA='https://wbapp.uve.weibo.com/wbapplua/wbpullad.lua';
const boot={code:200,ads:[{display_duration:5,daily_display_cnt:2,total_display_cnt:8,start_time:1700000000,end_time:1800000000,posids:['pos_mock'],creatives:[{res_type:'image',show_type:'full',res_width:1080,res_height:1920,skip_button_type:2,res_url:'https://mock.example/ad.jpg'}]}]};
check('boot preload suppressed',()=>{const r=rewrite(BOOT,boot),o=outBody(r);assert.equal(o.ads[0].display_duration,0);assert.equal(o.ads[0].daily_display_cnt,0);assert.equal(o.ads[0].total_display_cnt,0);assert.equal(r.network.length,0);});
const multipart='--mockboundary\r\nContent-Disposition: form-data; name="realtime"\r\n\r\n'+JSON.stringify({...boot,req_id:'mock'})+'\r\n--mockboundary--\r\n';
check('realtime multipart suppressed',()=>{const r=rewrite(REAL,multipart);assert.equal(r.done[0].body,'--mockboundary\r\nContent-Disposition: form-data; name="realtime"\r\n\r\n{"code":4000,"req_id":"mock"}\r\n--mockboundary--\r\n');});
check('realtime malformed exact passthrough',()=>{const r=rewrite(REAL,'unrecognized');assert.deepEqual(Object.keys(r.done[0]),[]);});
check('lua cached ads suppressed',()=>{const r=rewrite(LUA,{cached_ad:{ads:[{posid:'pos_findpage_test',adid:'1',show_count:1,duration:5},{posid:'other',adid:'2',show_count:'3',duration:'5'},{posid:'other',adid:'3',show_count:3,duration:5}]}}),o=outBody(r);assert.equal(o.cached_ad.ads.length,2);assert.equal(o.cached_ad.ads[0].show_count,'0');assert.equal(o.cached_ad.ads[0].duration,'0');assert.equal(o.cached_ad.ads[1].show_count,0);assert.equal(o.cached_ad.ads[1].duration,0);});
check('custom startup preserves URL duration',()=>{const r=rewrite(BOOT,boot,{startupImageSource:'custom',startupImageDuration:7,startupImageUrl:'https://mock.example/image.jpg'}),o=outBody(r);assert.equal(o.ads[0].display_duration,7);assert.equal(o.ads[0].creatives[0].res_url,'https://mock.example/image.jpg');assert.deepEqual(o.ads[0].monitor_url,[]);assert.equal(r.network.length,0);});
check('portrait URL injection only',()=>{const r=rewrite(BOOT,boot,{startupImageSource:'portrait'});assert.match(outBody(r).ads[0].creatives[0].res_url,/^https:\/\/imgapi\.cn\/api\.php\?zd=mobile&fl=meizi&_weibo_refresh=\d+$/);assert.equal(r.network.length,0);});
check('bing success Surge native HTTP',()=>{const r=rewrite(BOOT,boot,{startupImageSource:'bing'},{networkReply:[null,{status:200},JSON.stringify({images:[{urlbase:'/th?id=OHR.Mock_ZH-CN123'}]})]});assert.equal(r.network.length,1);assert.equal(r.network[0].url,'https://www.bing.com/HPImageArchive.aspx?format=js&idx=0&n=1&mkt=zh-CN');assert.equal(r.network[0].timeout,2);assert.equal(outBody(r).ads[0].creatives[0].res_url,'https://www.bing.com/th?id=OHR.Mock_ZH-CN123_1080x1920.jpg');assert.equal(r.writes[0][0],'weibo_startup_bing_v1');assert.equal(r.done.length,1);assert.equal(r.timers.size,0);});
check('bing failure closes ads safely',()=>{const r=rewrite(BOOT,boot,{startupImageSource:'bing'});assert.equal(r.network.length,1);assert.equal(outBody(r).ads[0].display_duration,0);assert.equal(r.done.length,1);assert.ok(JSON.parse(r.store.weibo_startup_bing_v1).retryAfter);});
check('bing timer fallback closes once',()=>{const r=rewrite(BOOT,boot,{startupImageSource:'bing'},{hangNetwork:true});assert.equal(r.done.length,0);assert.equal([...r.timers.values()][0].t,2500);r.flush();assert.equal(r.done.length,1);assert.equal(outBody(r).ads[0].display_duration,0);});
check('unsafe integer tokens preserved',()=>{const body='{"items":[{"category":"feed","data":{"id":90071992547409931,"bottom_bar_dyna":{"cell_item":{"ai_search":{}}}}}]}',r=rewrite('/2/statuses/container_timeline_hot',body);assert.match(r.done[0].body,/90071992547409931/);assert.doesNotMatch(r.done[0].body,/ai_search/);});

const profile={items:[{itemId:'profileme_mine',category:'group',type:'grid',header:{category:'mine',type:'header',itemId:'profileme_mine_head',vipView:{}}},{itemId:'100505_-_productcenter'},{itemId:'100505_-_album'}]};
check('profile injection and configured pruning',()=>{const o=outBody(rewrite('/2/profile/me',profile));assert.equal(o.items.some(x=>x.itemId==='100505_-_productcenter'),false);const entry=o.items.find(x=>x.itemId==='weibo_local_settings_v3');assert.ok(entry);assert.match(entry.click.modules[0].scheme,/sinaweibo:\/\/browser/);assert.ok(entry.click.modules[0].scheme.includes(encodeURIComponent(BASE)));assert.equal(o.items[0].header.vipView,undefined);});
