check('bing cache avoids request',()=>{const now=Date.now(),cache={day:new Date(now+8*3600000).toISOString().slice(0,10),timestamp:now,imageUrl:'https://www.bing.com/th?id=OHR.Mock_1080x1920.jpg'},r=rewrite(BOOT,boot,{}, {store:{[KEY]:JSON.stringify({startupImageSource:'bing'}),weibo_startup_bing_v1:JSON.stringify(cache)}});assert.equal(r.network.length,0);assert.equal(outBody(r).ads[0].creatives[0].res_url,cache.imageUrl);});
check('bing stale valid cache safe fallback',()=>{const now=Date.now(),cache={day:'2000-01-01',timestamp:now-2*86400000,imageUrl:'https://www.bing.com/th?id=OHR.Mock_1080x1920.jpg'},r=rewrite(BOOT,boot,{}, {store:{[KEY]:JSON.stringify({startupImageSource:'bing'}),weibo_startup_bing_v1:JSON.stringify(cache)}});assert.equal(r.network.length,1);assert.equal(outBody(r).ads[0].creatives[0].res_url,cache.imageUrl);});
check('binary body does not corrupt config',()=>{const r=run(BASE+'api/save',{method:'POST',headers,requestBody:new Uint8Array([123,125])});assert.equal(response(r).status,400);assert.equal(r.writes.length,0);});
check('query fragment settings URL works',()=>{const r=run(BASE+'api/config?foo=bar#x');assert.equal(response(r).status,200);assert.equal(r.network.length,0);});
check('all 33 routes available',()=>{const c=baseline.ctx;assert.equal(vm.runInContext('WeiboCore.ROUTES.length',c,{timeout:VM_TIMEOUT}),33);assert.equal(vm.runInContext('WeiboCore.ROUTES.every(x=>WeiboCore.resolveRoute("https://"+x.host+x.path+"?fixture=1")===x.name)',c,{timeout:VM_TIMEOUT}),true);});
